import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas=document.querySelector('#game'), hud=document.querySelector('#hud'), startScreen=document.querySelector('#start-screen'), pauseScreen=document.querySelector('#pause-screen'), resultScreen=document.querySelector('#result-screen');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.22;
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x171a17); scene.fog=new THREE.FogExp2(0x171a17,.032);
const camera=new THREE.PerspectiveCamera(88,innerWidth/innerHeight,.04,90); camera.rotation.order='YXZ'; scene.add(camera);
const hemi=new THREE.HemisphereLight(0x99a091,0x211c16,1.0); scene.add(hemi);
const moon=new THREE.DirectionalLight(0x91a1a0,1.25); moon.position.set(-5,9,2); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); moon.shadow.camera.left=-15;moon.shadow.camera.right=15;moon.shadow.camera.top=15;moon.shadow.camera.bottom=-15; scene.add(moon);
const warm=new THREE.PointLight(0xc78651,14,12,2); warm.position.set(-3.5,2.4,-5.5); scene.add(warm);
const warm2=new THREE.PointLight(0x9d754e,8,9,2); warm2.position.set(4,2.3,1); scene.add(warm2);
const world=new THREE.Group();scene.add(world); const solids=[], shootables=[], enemies=[];
function noiseTexture(base,accent,repeat=4){const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,256,256);for(let i=0;i<1800;i++){const a=Math.random()*.24;x.fillStyle=`rgba(${accent},${a})`;x.fillRect(Math.random()*256,Math.random()*256,Math.random()*8+1,Math.random()*5+1)}for(let i=0;i<32;i++){x.fillStyle=`rgba(0,0,0,${Math.random()*.18})`;x.fillRect(Math.random()*256,Math.random()*256,Math.random()*25+4,Math.random()*3+1)}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(repeat,repeat);t.colorSpace=THREE.SRGBColorSpace;return t}
const plaster=new THREE.MeshStandardMaterial({map:noiseTexture('#55564d','210,205,177',2),roughness:.96}), floorMat=new THREE.MeshStandardMaterial({map:noiseTexture('#393a34','178,160,127',5),roughness:1}), wood=new THREE.MeshStandardMaterial({map:noiseTexture('#302b24','155,122,82',3),roughness:.87}), metal=new THREE.MeshStandardMaterial({color:0x292c28,roughness:.58,metalness:.62}), debrisMat=new THREE.MeshStandardMaterial({color:0x514b3d,roughness:1});
function box(name,x,y,z,w,h,d,mat,collide=true,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.name=name;m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;world.add(m);if(collide)solids.push({x,z,w,d,y,h,obj:m});return m}
function wall(x,z,w,d,h=3.35){box('wall',x,h/2,z,w,h,d,plaster,true)}
// Shell, openings are deliberately offset for angled room-to-room sight lines.
wall(-9,0,.32,23);wall(9,0,.32,23);wall(0,-11,18,.32);wall(-5.65,11,6.7,.32);wall(5.65,11,6.7,.32);
// Interior thresholds
wall(-6.6,4,4.8,.24);wall(2.4,4,4.8,.24);wall(7.4,4,3.2,.24);
wall(-6.7,-2,4.6,.24);wall(2.4,-2,4.8,.24);wall(7.35,-2,3.3,.24);
wall(-3,6.9,.2,5.8);wall(3.2,6.9,.2,5.8);wall(-3,-6.4,.2,8.5);wall(3.2,-6.4,.2,8.5);
// Broken ceiling beams and broad ceiling shadow; open center allows bodycam framing.
box('ceiling slab',0,3.52,0,18,.18,22,new THREE.MeshStandardMaterial({color:0x292a25,roughness:1}),false,false);
for(let x=-8;x<=8;x+=4)box('ceiling beam',x,3.2,0,.16,.28,21,wood,false);
// floor and scattered physical details
box('floor',0,-.12,0,18,.24,22,floorMat,false,false);
// Windows as dim cold light wells
for(const z of [-7,0,8]){const glow=new THREE.Mesh(new THREE.PlaneGeometry(1.7,1.1),new THREE.MeshBasicMaterial({color:0x364448,transparent:true,opacity:.8}));glow.position.set(-8.81,2.05,z);glow.rotation.y=Math.PI/2;world.add(glow);const light=new THREE.PointLight(0x637b80,4,5,2);light.position.set(-7.3,2,z);scene.add(light);}
// furniture, overturned cabinets, barricades, junk
function crate(x,y,z,w,h,d,mat=wood){return box('furniture',x,y,z,w,h,d,mat,true)}
crate(-5.2,.78,-7.3,2.2,1.55,.65,wood);crate(-6.5,.48,-5.9,.8,.95,1.15,metal);
crate(5.7,.5,-7.1,2.5,1,1.1,wood);crate(6.6,.45,1.2,1.1,.9,1.5,wood);
crate(-5.7,.55,2.5,1.5,1.1,1.4,wood);crate(5,.48,6.1,2.4,.95,.8,metal);
crate(-1.9,.42,-4.8,1.1,.8,.7,wood);crate(1.9,.44,8.6,1.6,.86,.75,wood);
// Furniture legs and toppled chair-like silhouettes
for(const [x,z] of [[-5,-7],[5.3,-7],[5,6]]){for(const dx of [-.7,.7])box('leg',x+dx,.28,z,.12,.55,.13,metal,true)}
for(let i=0;i<52;i++){const x=(Math.random()-.5)*16,z=(Math.random()-.5)*19;if(Math.abs(x)<.7&&z>3)continue;const r=new THREE.Mesh(new THREE.BoxGeometry(.08+Math.random()*.22,.025,.07+Math.random()*.16),debrisMat);r.position.set(x,.02,z);r.rotation.y=Math.random()*3;world.add(r)}
// Dust motes suspended through the camera's lit volume
const dustGeo=new THREE.BufferGeometry(), dustPos=[];for(let i=0;i<150;i++)dustPos.push((Math.random()-.5)*17,Math.random()*3,(Math.random()-.5)*20);dustGeo.setAttribute('position',new THREE.Float32BufferAttribute(dustPos,3));const dust=new THREE.Points(dustGeo,new THREE.PointsMaterial({color:0xc2b99f,size:.023,transparent:true,opacity:.3}));scene.add(dust);
// Player starts inside the entry hall, already facing into the structure.
const player={pos:new THREE.Vector3(0,0,8.6),yaw:Math.PI,pitch:0,health:100,ammo:30,reserve:90,aim:false,crouch:false,sprint:false,locked:false,alive:true};camera.position.set(player.pos.x,1.62,player.pos.z);
// Weapon view model mounted low and close to chest camera.
const gun=new THREE.Group();camera.add(gun);const gunMat=new THREE.MeshStandardMaterial({color:0x252925,metalness:.7,roughness:.42}), polymer=new THREE.MeshStandardMaterial({color:0x33352f,roughness:.82});
function gunBox(x,y,z,w,h,d,mat){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.set(x,y,z);m.castShadow=true;gun.add(m);return m}
gunBox(.34,-.29,-.62,.17,.18,.54,gunMat);gunBox(.34,-.28,-.35,.115,.11,.44,polymer);gunBox(.34,-.39,-.56,.11,.24,.14,polymer);gunBox(.34,-.22,-.91,.067,.067,.72,gunMat);gunBox(.34,-.22,-1.28,.09,.09,.13,gunMat);gunBox(.34,-.15,-.54,.12,.075,.22,polymer);gunBox(.34,-.09,-.57,.055,.05,.1,gunMat);gunBox(.34,-.22,-.16,.22,.11,.23,polymer);
const muzzle=new THREE.PointLight(0xffa45a,0,5,2);camera.add(muzzle);const flashMat=new THREE.MeshBasicMaterial({color:0xffb45c,transparent:true,opacity:.95});const flash=new THREE.Mesh(new THREE.ConeGeometry(.12,.42,8),flashMat);flash.rotation.x=-Math.PI/2;flash.position.set(.34,-.22,-1.48);flash.visible=false;gun.add(flash);
// Enemy models are original procedural low-detail silhouettes rather than external assets.
const enemyMat=new THREE.MeshStandardMaterial({color:0x34362f,roughness:.9}), skinMat=new THREE.MeshStandardMaterial({color:0x686050,roughness:.95}), vestMat=new THREE.MeshStandardMaterial({color:0x252923,roughness:.95});
function makeEnemy(x,z,seed){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);const torso=new THREE.Mesh(new THREE.BoxGeometry(.52,.7,.32),enemyMat);torso.position.y=1.17;torso.castShadow=true;g.add(torso);const vestMesh=new THREE.Mesh(new THREE.BoxGeometry(.55,.38,.35),vestMat);vestMesh.position.set(0,1.22,-.025);vestMesh.castShadow=true;g.add(vestMesh);const head=new THREE.Mesh(new THREE.SphereGeometry(.19,10,8),skinMat);head.position.y=1.68;head.castShadow=true;g.add(head);const hood=new THREE.Mesh(new THREE.SphereGeometry(.2,10,7,0,Math.PI*2,0,Math.PI*.56),vestMat);hood.position.y=1.72;g.add(hood);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.2,.65,.23),enemyMat);leg.position.set(s*.15,.38,0);leg.castShadow=true;g.add(leg);const arm=new THREE.Mesh(new THREE.BoxGeometry(.17,.57,.18),enemyMat);arm.position.set(s*.36,1.12,-.14);arm.rotation.x=-.25;g.add(arm)}const rifle=new THREE.Mesh(new THREE.BoxGeometry(.09,.09,.68),gunMat);rifle.position.set(.25,.97,-.43);g.add(rifle);const hit=new THREE.Mesh(new THREE.BoxGeometry(.68,1.95,.5),new THREE.MeshBasicMaterial({visible:false}));hit.position.y=1;g.add(hit);const e={group:g,hit,health:100,alive:true,seed,fireAt:2+Math.random()*3,phase:Math.random()*5,home:new THREE.Vector3(x,0,z),cover:0};enemies.push(e);shootables.push({mesh:hit,enemy:e});return e}
makeEnemy(-5.4,-7.5,1);makeEnemy(5.8,-5.8,2);makeEnemy(1.5,1.0,3);
// Doors, wall-mounted practicals and environmental decals
for(const [x,z] of [[-3.1,-.5],[3.3,-5],[-7.6,6]]){const lamp=new THREE.PointLight(0xd19a5e,7,4,2);lamp.position.set(x,2.7,z);scene.add(lamp);const bulb=new THREE.Mesh(new THREE.BoxGeometry(.28,.07,.14),new THREE.MeshBasicMaterial({color:0xe1b77a}));bulb.position.set(x,3.15,z);world.add(bulb)}
function addDecal(x,y,z,w,h,rot,color=0x34342e){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.38,side:THREE.DoubleSide}));m.position.set(x,y,z);m.rotation.y=rot;world.add(m)}
addDecal(-8.81,1.3,-2,1.3,.8,Math.PI/2,0x51433a);addDecal(8.81,1.7,-7,1.4,1.2,-Math.PI/2,0x343b37);
// Audio: generated per action with WebAudio, no downloaded sound assets needed.
let audioCtx=null, master=null;function initAudio(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.28;master.connect(audioCtx.destination);const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=47;gain.gain.value=.025;osc.connect(gain);gain.connect(master);osc.start()}
function noiseBurst(duration,filterFreq,volume){if(!audioCtx)return;const n=Math.floor(audioCtx.sampleRate*duration),b=audioCtx.createBuffer(1,n,audioCtx.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);const src=audioCtx.createBufferSource(),f=audioCtx.createBiquadFilter(),g=audioCtx.createGain();src.buffer=b;f.type='lowpass';f.frequency.value=filterFreq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);src.connect(f);f.connect(g);g.connect(master);src.start()}
function shootSound(){noiseBurst(.22,1500,.8);if(!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(115,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(38,audioCtx.currentTime+.12);g.gain.setValueAtTime(.3,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.14);o.connect(g);g.connect(master);o.start();o.stop(audioCtx.currentTime+.15)}
function reloadSound(){noiseBurst(.36,850,.24)}function hurtSound(){noiseBurst(.3,500,.45)}
// Controls and combat state.
const keys={};let gameActive=false, paused=false, startTime=0,lastShot=0,reloading=false,reloadEnd=0,weaponKick=0,walkPhase=0,toastTimer=0,damageCooldown=0,enemyCount=enemies.length;
const raycaster=new THREE.Raycaster();raycaster.far=45;
function updateObjective(){const alive=enemies.filter(e=>e.alive).length;document.querySelector('#objective-sub').innerHTML=`Hostiles remaining: <b>${alive}</b>`;if(alive===0){document.querySelector('#objective-text').textContent='SITE SECURED';setTimeout(()=>endGame(true),1400)}}
function showToast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1300)}
function playHit(){const el=document.querySelector('#hit-marker');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),120)}
function shoot(){if(!gameActive||paused||!player.locked||reloading||!player.alive)return;const now=performance.now()/1000;if(now-lastShot<.13)return;lastShot=now;if(player.ammo<=0){showToast('MAGAZINE EMPTY — PRESS R');return}player.ammo--;document.querySelector('#ammo').textContent=player.ammo;shootSound();weaponKick=Math.min(weaponKick+.16,.32);flash.visible=true;muzzle.intensity=18;setTimeout(()=>{flash.visible=false;muzzle.intensity=0},48);const spread=player.aim?.002:.014;raycaster.setFromCamera(new THREE.Vector2((Math.random()-.5)*spread,(Math.random()-.5)*spread),camera);const candidates=shootables.filter(s=>s.enemy.alive).map(s=>s.mesh);const hits=raycaster.intersectObjects(candidates,false);if(hits.length){const e=shootables.find(s=>s.mesh===hits[0].object)?.enemy;if(e){e.health-=player.aim?55:42;playHit();if(e.health<=0){e.alive=false;e.group.rotation.x=.4;e.group.position.y=-.12;showToast('HOSTILE DOWN');updateObjective()}}} }
function reload(){if(!gameActive||reloading||player.ammo===30||player.reserve<=0)return;reloading=true;reloadEnd=performance.now()+1650;showToast('RELOADING');reloadSound();gun.rotation.x=.19;setTimeout(()=>gun.rotation.x=0,420)}
function begin(){initAudio();startTime=performance.now();gameActive=true;paused=false;startScreen.classList.add('hidden');resultScreen.classList.add('hidden');hud.classList.remove('hidden');renderer.domElement.requestPointerLock?.();player.locked=true}
document.querySelector('#deploy').addEventListener('click',begin);document.querySelector('#resume').addEventListener('click',()=>{renderer.domElement.requestPointerLock?.();paused=false;pauseScreen.classList.add('hidden');player.locked=true});document.querySelector('#restart').addEventListener('click',()=>location.reload());
document.addEventListener('pointerlockchange',()=>{if(gameActive&&!document.pointerLockElement&&!paused){paused=true;player.locked=false;pauseScreen.classList.remove('hidden')}});
document.addEventListener('mousemove',e=>{if(!player.locked)return;player.yaw-=e.movementX*.00215;player.pitch=Math.max(-1.34,Math.min(1.34,player.pitch-e.movementY*.0019))});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyR')reload();if(e.code==='Escape'&&gameActive){paused=!paused;pauseScreen.classList.toggle('hidden',!paused);if(!paused)renderer.domElement.requestPointerLock?.();else document.exitPointerLock?.()}if(e.code==='ControlLeft'||e.code==='ControlRight'){player.crouch=true;document.querySelector('#stance').textContent='CROUCHED'}});document.addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='ControlLeft'||e.code==='ControlRight'){player.crouch=false;document.querySelector('#stance').textContent='STANDING'}});
document.addEventListener('mousedown',e=>{if(e.button===0)shoot();if(e.button===2){player.aim=true;document.body.classList.add('aiming')}});document.addEventListener('mouseup',e=>{if(e.button===2){player.aim=false;document.body.classList.remove('aiming')}});document.addEventListener('contextmenu',e=>e.preventDefault());
// Simple collision against world AABBs keeps movement grounded and prevents wall clipping.
function collides(x,z){const r=.32;for(const s of solids){if(s.y-s.h/2>1.8)continue;if(x+r>s.x-s.w/2&&x-r<s.x+s.w/2&&z+r>s.z-s.d/2&&z-r<s.z+s.d/2)return true}return Math.abs(x)>8.35||Math.abs(z)>10.35}
function canSee(pos){const dir=pos.clone().sub(camera.position),dist=dir.length();raycaster.set(camera.position,dir.normalize());raycaster.far=dist;const walls=world.children.filter(o=>o.name==='wall'||o.name==='furniture');const hit=raycaster.intersectObjects(walls,false)[0];return !hit||hit.distance>dist-.45}
function enemyUpdate(dt,time){for(const e of enemies){if(!e.alive)continue;e.phase+=dt*5;const to=player.pos.clone().sub(e.group.position);to.y=0;const dist=to.length();const visible=dist<15&&canSee(e.group.position.clone().add(new THREE.Vector3(0,1.2,0)));e.group.rotation.y=Math.atan2(to.x,to.z)+Math.PI; if(visible){if(dist>5.5&&time-e.seed>1){const move=to.normalize().multiplyScalar(dt*.43);const nx=e.group.position.x+move.x,nz=e.group.position.z+move.z;if(!collides(nx,nz)){e.group.position.x=nx;e.group.position.z=nz}}if(time>e.fireAt&&dist<13){e.fireAt=time+2.5+Math.random()*2;enemyFire(e,dist)}}e.group.position.y=Math.sin(e.phase)*.008}}
function enemyFire(e,dist){if(!gameActive||!player.alive)return;const d=dist;const chance=Math.max(.12,.48-d*.018);if(Math.random()>chance)return;damageCooldown=performance.now()+180;player.health=Math.max(0,player.health-(7+Math.floor(Math.random()*9)));document.querySelector('#health').textContent=player.health;document.querySelector('#health-fill').style.width=player.health+'%';document.querySelector('#damage-flash').style.opacity='.8';setTimeout(()=>document.querySelector('#damage-flash').style.opacity='0',170);hurtSound();if(player.health<=0){player.alive=false;setTimeout(()=>endGame(false),500)}}
function endGame(won){gameActive=false;player.locked=false;document.exitPointerLock?.();hud.classList.add('hidden');pauseScreen.classList.add('hidden');resultScreen.classList.remove('hidden');document.querySelector('#result-kicker').textContent=won?'MISSION COMPLETE':'OFFICER DOWN';document.querySelector('#result-title').innerHTML=won?'SITE SECURED<span>.</span>':'OPERATION FAILED<span>.</span>';document.querySelector('#result-copy').textContent=won?'All hostiles neutralized. Site secured.':'You were incapacitated before the building was cleared.'}
function updateClock(){if(!startTime)return;const seconds=Math.floor((performance.now()-startTime)/1000),h=String(Math.floor(seconds/3600)).padStart(2,'0'),m=String(Math.floor(seconds/60)%60).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');document.querySelector('#clock').textContent=`${h}:${m}:${s}`}
function update(dt,time){if(!gameActive||paused)return;updateClock();if(reloading&&performance.now()>reloadEnd){const need=30-player.ammo,load=Math.min(need,player.reserve);player.ammo+=load;player.reserve-=load;document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;reloading=false;showToast('MAGAZINE READY')}
let forward=(keys.KeyW?1:0)-(keys.KeyS?1:0),side=(keys.KeyD?1:0)-(keys.KeyA?1:0);player.sprint=!!keys.ShiftLeft&&!player.aim&&!player.crouch&&forward>0;const speed=player.crouch?1.55:player.sprint?5.25:3.05;const len=Math.hypot(forward,side)||1;forward/=len;side/=len;const sin=Math.sin(player.yaw),cos=Math.cos(player.yaw);const dx=(side*cos+forward*sin)*speed*dt,dz=(-side*sin+forward*cos)*speed*dt;let nx=player.pos.x+dx,nz=player.pos.z+dz;if(!collides(nx,player.pos.z))player.pos.x=nx;if(!collides(player.pos.x,nz))player.pos.z=nz;const moving=!!(forward||side);if(moving)walkPhase+=dt*(player.sprint?12:7);const bob=moving?Math.sin(walkPhase)* (player.sprint?.045:.022):0;camera.position.set(player.pos.x,player.crouch?1.13:1.62,player.pos.z);camera.rotation.set(player.pitch+(moving?Math.cos(walkPhase*.5)*.003:0),player.yaw,0,'YXZ');const targetX=player.aim?.08:.0,targetY=player.aim?-.22:-.29;gun.position.x+=(targetX-gun.position.x)*Math.min(1,dt*9);gun.position.y+=(targetY+bob-gun.position.y)*Math.min(1,dt*12);gun.position.z+=(player.aim?.045:0-gun.position.z)*Math.min(1,dt*8);weaponKick=Math.max(0,weaponKick-dt*.72);gun.position.z+=weaponKick;gun.rotation.x=-weaponKick*.55;camera.fov+=(player.aim?64:player.sprint?94:88-camera.fov)*Math.min(1,dt*7);camera.updateProjectionMatrix();enemyUpdate(dt,time);const t=Date.now()/1000;warm.intensity=11+Math.sin(t*7)*2;warm2.intensity=7+Math.sin(t*4.3+2)*1.3;}
let previous=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-previous)/1000);previous=now;update(dt,now/1000);const a=dust.geometry.attributes.position;for(let i=0;i<a.count;i++){a.array[i*3+1]+=.0012;if(a.array[i*3+1]>3)a.array[i*3+1]=.1}a.needsUpdate=true;renderer.render(scene,camera)}requestAnimationFrame(frame);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65))});

