*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101210;color:#e8e8df;font-family:'IBM Plex Mono',monospace}
#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#101210}
#game{position:absolute;inset:0;width:100%;height:100%;display:block;filter:contrast(1.13) saturate(.72)}
.lens-vignette{position:absolute;inset:-1%;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(0,0,0,.24) 77%,rgba(0,0,0,.77) 130%),linear-gradient(180deg,rgba(0,0,0,.15),transparent 25%,transparent 72%,rgba(0,0,0,.32));z-index:2}
.grain{position:absolute;inset:-50%;z-index:3;pointer-events:none;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");animation:grain .22s steps(2) infinite}
.scanline{position:absolute;inset:0;pointer-events:none;z-index:4;opacity:.08;background:repeating-linear-gradient(0deg,transparent 0 2px,rgba(0,0,0,.55) 3px 4px)}
@keyframes grain{0%{transform:translate(0,0)}
25%{transform:translate(-1%,1%)}
50%{transform:translate(1%,-1%)}
75%{transform:translate(-1%,-1%)}
100%{transform:translate(1%,1%)}
}
.hidden{display:none!important}
.screen{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(5,7,6,.86),rgba(8,10,9,.56) 57%,rgba(5,6,5,.79));backdrop-filter:blur(2px)}
.start-card{width:min(590px,90vw);padding:30px 42px 25px;background:rgba(13,16,14,.91);border:1px solid rgba(220,224,205,.18);box-shadow:0 25px 100px #0009;position:relative}
.start-card:before,.pause-panel:before{content:'';position:absolute;left:-1px;top:-1px;width:62px;height:2px;background:#d3d5bd}
.brand{display:flex;align-items:center;gap:12px}
.brand-mark{font:800 30px 'Barlow Condensed';letter-spacing:-2px;color:#d4d7c7;border:1px solid #676b5a;width:48px;height:42px;text-align:center;line-height:39px}
.brand-mark span,.brand-title span,.pause-panel h2 span{color:#d39c5d}
.brand-overline,.side-kicker{font-size:9px;letter-spacing:2px;color:#9da18f}
.brand-title{font:700 19px 'Barlow Condensed';letter-spacing:2px;margin-top:1px}
.rule{height:1px;background:#33372f;margin:20px 0 17px}
.mission-line{display:flex;justify-content:space-between;font-size:9px;letter-spacing:1.5px;color:#adb09e}
.status-pill{color:#d7ac70}
.status-pill:before{content:''}
h1{font:700 47px/.88 'Barlow Condensed';letter-spacing:1px;margin:17px 0 12px;color:#ecece4}
.brief{font:12px/1.65 'IBM Plex Mono';color:#a9ad9f;max-width:455px;margin:0}
.brief-stats{display:flex;gap:32px;border-top:1px solid #30342d;border-bottom:1px solid #30342d;margin:19px 0 16px;padding:12px 0}
.brief-stats div{display:flex;flex-direction:column;gap:5px}
.brief-stats small{font-size:8px;letter-spacing:1px;color:#777d70}
.brief-stats b{font-size:9px;font-weight:500;letter-spacing:.3px;color:#d7d8ce}
.brief-stats b.threat{color:#d49d64}
button{border:0;background:#d4d5c7;color:#141613;padding:13px 18px;font:700 12px 'IBM Plex Mono';letter-spacing:1.3px;width:100%;text-align:left;cursor:pointer;transition:background .16s,transform .16s}
button:hover{background:#eeeede;transform:translateY(-1px)}
button span{float:right;font-size:16px;line-height:12px}
.controls{display:grid;grid-template-columns:repeat(4,1fr);gap:10px 7px;margin:18px 0 19px;color:#818678;font-size:8px;align-items:center}
.controls>div{display:flex;align-items:center;gap:6px;white-space:nowrap}
kbd{font:9px 'IBM Plex Mono';color:#d3d5c8;border:1px solid #4b5046;padding:4px 5px;background:#1a1d19}
.card-foot{padding-top:12px;border-top:1px solid #30342d;display:flex;justify-content:space-between;color:#676d62;font-size:8px;letter-spacing:.5px}
.screen-side{width:230px;margin-left:40px;padding-top:120px;color:#bbc0af;align-self:stretch;display:flex;flex-direction:column;justify-content:center}
.side-kicker{font-size:9px}
.side-line{width:44px;height:1px;background:#d39c5d;margin:16px 0}
.screen-side p{font:italic 13px/1.8 'IBM Plex Mono';color:#b4b8aa}
.side-meta{font-size:8px;line-height:1.8;color:#73796c;margin-top:18px}
.side-meta span{color:#c09a6b}
.side-bottom{margin-top:70px;font-size:8px;letter-spacing:1px;line-height:1.8;color:#73796c}
.boot-mark{position:absolute;z-index:5;left:20px;bottom:15px;color:#9ca09280;font-size:8px;letter-spacing:1px}
.boot-mark span{color:#d1d2c3;font-weight:bold}
.boot-mark i{font-style:normal;color:#686e62}
#hud{position:absolute;inset:0;z-index:6;pointer-events:none;text-shadow:0 1px 5px #000}
.topline{position:absolute;top:24px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:center;color:#e1e2d7;font-size:10px;letter-spacing:1px}
.rec{color:#e1e2d7}
.rec i,.weapon-mode i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#c96e59;margin-right:5px;box-shadow:0 0 10px #d65b42;animation:blink 1.4s infinite}
.rec b{font-weight:400;color:#aaa}
.mission-tag{font-size:9px;color:#bdc0b3}
.mission-tag span{color:#b98756;padding:0 7px}
.signal{font-size:9px;color:#bac2ac}
.signal:first-letter{color:#8da282}
.signal span{color:#858b7c;margin-left:7px}
.objective{position:absolute;top:22%;left:30px;border-left:2px solid #d2a06b;padding:4px 0 5px 12px}
.obj-label{font-size:8px;letter-spacing:1.4px;color:#a6a99b}
.objective #objective-text{font:600 19px 'Barlow Condensed';letter-spacing:1.4px;margin:4px 0}
.objective #objective-sub{font-size:9px;color:#9da394}
.objective #objective-sub b{color:#d3d3c7;font-weight:500}
.compass{position:absolute;top:78px;left:50%;transform:translateX(-50%);width:100px;text-align:center;font-size:9px;color:#c2c4b8}
.compass span{font-size:8px;color:#d4aa74}
.compass-line{height:8px;width:1px;background:#d4aa74;margin:5px auto 3px}
.compass small{font-size:8px;color:#989c90}
.center-reticle{position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.88}
.center-reticle i{position:absolute;top:8px;left:7px;width:4px;height:4px;border:1px solid #d4d8c8;border-radius:50%}
.center-reticle b{position:absolute;top:0;left:8px;width:1px;height:5px;background:#d4d8c8;box-shadow:0 13px #d4d8c8,-6px 6px #d4d8c8,6px 6px #d4d8c8}
.center-reticle.aim{transform:translate(-50%,-50%) scale(.67);filter:drop-shadow(0 0 3px #fff)}
.hit-marker{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);opacity:0;color:#e4d7b6;font:20px Arial;transition:opacity .08s}
.hit-marker.show{opacity:1}
.bottom-left{position:absolute;left:30px;bottom:28px;width:155px}
.health-title{font-size:8px;letter-spacing:1.3px;color:#c1c5b6}
.health-title span{float:right;font-size:7px;color:#92aa87}
.health-track{height:3px;background:#41443a;margin:7px 0 4px}
.health-track i{display:block;width:100%;height:100%;background:#c2c4ad;transition:width .2s,background .2s}
.health-num strong{font:500 24px 'Barlow Condensed';color:#e1e2d8}
.health-num small{font-size:9px;color:#858b7e}
.stance{margin-top:10px;font-size:8px;color:#8f9487;letter-spacing:.8px}
.stance b{color:#d2d3c7;margin-left:6px;font-weight:500}
.bottom-right{position:absolute;right:32px;bottom:26px;text-align:right}
.weapon-name{font:600 16px 'Barlow Condensed';letter-spacing:1px;color:#ecece2}
.weapon-name span{font:8px 'IBM Plex Mono';color:#a4a99a;margin-left:7px}
.ammo{display:flex;align-items:baseline;justify-content:flex-end;gap:7px;margin-top:1px}
.ammo strong{font:500 42px/.95 'Barlow Condensed';color:#f0f0e5}
.ammo span,.ammo small{color:#8e9386;font-size:14px}
.ammo-label{font-size:7px;letter-spacing:1px;color:#969b8e}
.ammo-label span{color:#bd9a6e;padding:0 4px}
.weapon-mode{font-size:8px;color:#b1b5a8;margin-top:8px}
.weapon-mode i{width:5px;height:5px;background:#9aa68b;box-shadow:none}
.weapon-mode b{color:#d3d3c8;font-weight:400;border:1px solid #777c70;padding:2px 4px;margin-left:5px;font-size:7px}
.bodycam-stamp{position:absolute;left:30px;top:50%;transform:translateY(-50%);font-size:7px;line-height:1.8;letter-spacing:.4px;color:#b9bead9c}
.toast{position:absolute;top:32%;left:50%;transform:translate(-50%,-50%);font-size:10px;letter-spacing:1px;color:#e0d1b3;opacity:0;transition:opacity .2s}
.toast.show{opacity:1}
.interact-hint{position:absolute;bottom:18%;left:50%;transform:translateX(-50%);color:#e1dfd1;background:#1119;padding:8px 13px;border:1px solid #9a9b8666;font-size:9px;letter-spacing:1px;display:none}
#damage-flash{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse,transparent 30%,rgba(155,30,18,.48));transition:opacity .1s}
.pause-panel{position:relative;width:min(470px,90vw);padding:44px;background:rgba(13,16,14,.94);border:1px solid #d7ddc42b;box-shadow:0 25px 100px #0009}
.pause-panel h2{font:700 48px 'Barlow Condensed';margin:12px 0}
.pause-panel p{font-size:11px;color:#a9ad9f;line-height:1.7;margin-bottom:26px}
.pause-panel button{margin-top:6px}
.pause-panel .brand-overline{letter-spacing:2px}
.pause-panel kbd{font-size:10px}
.result-panel{border-color:#d0aa7566}
@keyframes blink{50%{opacity:.35}
}
body.aiming .center-reticle{transform:translate(-50%,-50%) scale(.68)}
@media(max-width:750px){.screen{overflow:auto;align-items:flex-start;padding:20px}
.start-card{padding:24px;margin:auto}
.screen-side{display:none}
.controls{grid-template-columns:repeat(2,1fr)}
.brief-stats{gap:10px;justify-content:space-between}
.brief-stats b{font-size:8px}
.topline{left:15px;right:15px;top:14px}
.mission-tag{display:none}
.objective{left:15px;top:18%}
.bottom-left{left:15px;bottom:16px}
.bottom-right{right:15px;bottom:16px}
.bodycam-stamp{display:none}
}

